def prepare_collision():
 data=json.loads((ROOT/'scripts/collision-layout.json').read_text(encoding='utf-8'))
 (ROOT/'shared/src/collisionLayout.ts').write_text('// Generated by prepare-regions.py from scripts/collision-layout.json. Native world pixels.\nexport const COLLISION_LAYOUT = '+json.dumps(data,ensure_ascii=False,indent=1)+';\n',encoding='utf-8')
 (ROOT/'shared/src/regionalMapData.ts').write_text('export const REGIONAL_MAP_DATA = '+json.dumps(DATA,ensure_ascii=False,indent=1)+';\n',encoding='utf-8')

def prepare():
 manifest={}
 for slug,data in DATA.items():
  archive=ARCHIVE/slug
  out=ROOT/'client/public/assets/regions'/slug; out.mkdir(parents=True,exist_ok=True)
  source=archive/'clean-scene.png'
  if not source.exists():
   source = out/'scene.webp'
  if not source.exists(): continue
  im=Image.open(source).convert('RGB')
  assert im.size==(1672,941), (slug,im.size)
  im.save(out/'scene.webp',quality=94,method=6)
  im.resize((256,144),Image.Resampling.LANCZOS).save(out/'minimap.webp',quality=88)
  if slug == 'ha-tinh':
   rescue_src = archive / 'rescue-scene.png'
   if not rescue_src.exists():
    rescue_src = out / 'rescue-scene.webp'
   if rescue_src.exists():
    rim = Image.open(rescue_src).convert('RGB')
    assert rim.size == (1672, 941)
    rim.save(out / 'rescue-scene.webp', quality=94, method=6)
    rim.resize((256, 144), Image.Resampling.LANCZOS).save(out / 'rescue-minimap.webp', quality=88)
  # A small actual-landmark crop for the native HUD, not a new drawing.
  crop={'hai-phong':(610,173,1030,463),'quang-ninh':(835,22,1080,245),'ninh-binh':(575,394,783,550),'thanh-hoa':(630,155,1048,324),'nghe-an':(711,254,1095,424),'ha-tinh':(817,102,1025,419)}[slug]
  icon=im.crop(crop); icon.thumbnail((56,44),Image.Resampling.LANCZOS); icon.save(out/'icon.webp',quality=90)
  layers=[]
  for spec in data['foreground']:
   poly=spec['polygon'];x0,y0=min(p[0] for p in poly),min(p[1] for p in poly);x1,y1=max(p[0] for p in poly)+1,max(p[1] for p in poly)+1
   im.crop((x0,y0,x1,y1)).save(out/f"{spec['key']}.webp",quality=94,method=6)
   layers.append(dict(**spec,x=x0,y=y0,width=x1-x0,height=y1-y0))
  manifest[slug]=layers
  (out/'layers.json').write_text(json.dumps(layers,ensure_ascii=False,indent=2),encoding='utf-8')
  print(slug,sum(p.stat().st_size for p in out.glob('*')))
 (ROOT/'shared/src/regionalMapData.ts').write_text('export const REGIONAL_MAP_DATA = '+json.dumps(DATA,ensure_ascii=False,indent=1)+';\n',encoding='utf-8')
 (ROOT/'client/src/game/regionalLayers.ts').write_text('export const REGIONAL_LAYERS:Record<string,{key:string;x:number;y:number;width:number;height:number;depth:number;polygon:number[][]}[]> = '+json.dumps(manifest,ensure_ascii=False,indent=1)+';\n',encoding='utf-8')

if __name__=='__main__':
 import sys
 prepare_collision()
 if '--geometry-only' not in sys.argv: prepare()
